                ss_serifu_kind = master_girl_res_tbl[1][7];
                sss_sound = master_girl_res_tbl[2][7];
                break;
            case 6:
                ss_serifu = master_girl_res_tbl[0][8];
                ss_serifu_kind = master_girl_res_tbl[1][8];
